//! Actual native consumers and production service. Provider identities are synthetic.
use super::*;
#[test]#[ignore="Serialized disposable DB composition only"]fn ux1_direct_join_repeated_chat_and_original_retry_survive_configuration_and_presence_churn(){
 assert_eq!(std::env::var("NT2_AUTH1_COMPOSITION").as_deref(),Ok("1"));let root=repo().join("spikes/noita-entry/.build").join(format!("ux1-join-chat-composition-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();
 tauri::async_runtime::block_on(async{
  let mut f=Fixture::start(&root);let mut stores=Stores(Vec::new());let origin=f.private["origin"].as_str().unwrap().to_owned();let mut a=client(&f,&root.join("host"),&mut stores);let mut b=client(&f,&root.join("peer"),&mut stores);for c in [&mut a,&mut b]{c.enable_automatic_setup();c.enable_lc1();}
  a.fresh_login(&origin,true,"google",None).await.unwrap();b.fresh_login(&origin,true,"twitch",None).await.unwrap();Browser::new(&a).provider(&mut a).await;Browser::new(&b).provider(&mut b).await;let host=projection(&mut a).await;projection(&mut b).await;
  let config=json!({"seed":123,"seedPolicy":"shared-fixed","randomizeLoot":false,"mode":"core","requiredCapabilities":a.info.as_ref().unwrap().compatibility.as_ref().unwrap().capabilities,"settings":[]});a.ux1_create(serde_json::from_value(json!({"name":host["entitlements"]["generatedLobbyName"],"capacity":8,"visibility":"public","allow_guests":false,"config":config})).unwrap()).await.unwrap();let room=a.room.as_ref().unwrap().room_id.clone().unwrap();assert!(b.setup.preview.is_none());b.join_selected(&room,None).await.unwrap();assert_eq!(b.room.as_ref().unwrap().room_id.as_deref(),Some(room.as_str()));assert!(b.pending.lock().unwrap().is_none());let stale=serde_json::to_value(&b.room).unwrap();let bid=b.desktop.as_ref().unwrap().account.clone();let bdesktop=b.desktop.as_ref().unwrap().id.clone();let mut accepted=Vec::new();
  for i in 0..8{f.command(json!({"op":"advance","ms":11000}));a.ux1_refresh().await.unwrap();let mut config=serde_json::to_value(a.room.as_ref().unwrap().config.clone()).unwrap();config["seed"]=json!(456+i);change(&mut a,"configure",config).await.unwrap();let mut presence=a.request(false);presence.presence=Some(wire::Presence{present:Some(true)});let response=a.rpc(&presence,false,false).await.unwrap();a.absorb(&response);
   let text=format!("Repeated native message {i} · 你好");if i==3{b.ux1_fixture_lose_next_reply();assert!(b.chat_send(text.clone()).await.is_err());let original=serde_json::to_value(&b.chat_retry.as_ref().unwrap().request).unwrap();a.ux1_refresh().await.unwrap();change(&mut a,"policy",json!({"capacity":7})).await.unwrap();assert!(b.chat_send("different uncertain intent".into()).await.is_err());assert_eq!(serde_json::to_value(&b.chat_retry.as_ref().unwrap().request).unwrap(),original);b.retry_chat().await.unwrap();assert_eq!(b.chat_feedback["request"],original["requestId"]);}else{b.chat_send(text.clone()).await.unwrap();}assert_eq!(b.chat_feedback["status"],"accepted");accepted.push(text);assert_eq!(serde_json::to_value(&b.room).unwrap(),stale,"Chat must succeed from its original stale room/config snapshot");
  }
  a.ux1_refresh().await.unwrap();assert!(a.room.as_ref().unwrap().config_revision>b.room.as_ref().unwrap().config_revision);change(&mut a,"moderate",json!({"accountId":bid,"desktopId":bdesktop,"action":"mute"})).await.unwrap();assert_eq!(b.chat_send("definitively refused draft".into()).await.unwrap_err(),"CHAT_MUTED");assert!(b.chat_retry.is_none());assert_eq!(b.chat_feedback["status"],"failed");a.ux1_refresh().await.unwrap();change(&mut a,"moderate",json!({"accountId":bid,"desktopId":bdesktop,"action":"unmute"})).await.unwrap();b.chat_send("Separate corrected message".into()).await.unwrap();accepted.push("Separate corrected message".into());a.collect_chat().await.unwrap();assert_eq!(a.chat.len(),accepted.len());let actual=a.chat.iter().map(|m|m.text.clone().unwrap()).collect::<Vec<_>>();assert_eq!(actual,accepted,"Lost response retry must produce one canonical row");let mut sequences=a.chat.iter().map(|m|m.sequence.unwrap()).collect::<Vec<_>>();sequences.sort();sequences.dedup();assert_eq!(sequences.len(),accepted.len());
  a.logout().await.unwrap();b.logout().await.unwrap();drop(stores);f.close();std::fs::write(root.join("result.json"),serde_json::to_vec_pretty(&json!({"passed":true,"actualDesktopCoreAndProductionService":true,"directJoinWithoutPriorReview":true,"repeatedMessages":accepted.len(),"configurationAndPresenceChurn":true,"staleClientSnapshotRetained":true,"originalRequestRetryNoDuplicate":true,"definitiveMuteRefusalAndSeparateCorrectedSend":true,"syntheticProviderIdentities":true,"noitaLaunched":false,"schemaCleanupVerified":true,"protectedFixtureTargetsRemoved":true})).unwrap()).unwrap();eprintln!("UX1 direct Join/chat composition passed: {}",root.display());
 });
}
